test.each(['group','remove','new-only'].flatMap(shape=>[false,true].map(failThird=>[shape,failThird] as const)))('one-off weekly replacement %s keeps the original on later failure: %s',async(shape,failThird)=>{const {t,token,send}=await setup();vi.stubEnv('WHATSAPP_ACCESS_TOKEN','synthetic');vi.stubEnv('WHATSAPP_PHONE_NUMBER_ID','fictional');vi.stubEnv('INTUNE_REMINDER_TEMPLATE_APPROVED','1');vi.stubEnv('INTUNE_REMINDER_TEMPLATE','intune_requested_reminder_v1');await send('Pilates three times a week at 10 am',{introduced:true,reply:'Kept Pilates.',actions:[{type:'save',kind:'plan',label:'Pilates',evidence:'Pilates three times a week at 10 am',targetNumber:3,timePhrase:'10 am'}],tasks:[]},'replace-plan');const c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''}),id=c.state.records[0].id;await send('Remind me about Pilates tomorrow at 9:30 am',{introduced:true,reply:'Reminder set.',actions:[{type:'reminder',targetId:id,evidence:'Remind me about Pilates tomorrow at 9:30 am',permissionEvidence:'Remind me about Pilates tomorrow at 9:30 am',datePhrase:'tomorrow',timePhrase:'9:30 am',repeat:'once'}],tasks:[]},'replace-once');const old=(await t.query(q('pilotReminders:view'),{token}))[0];if(failThird)await t.run(async ctx=>{const u=await ctx.db.query('users').withIndex('by_token',q=>q.eq('token',token)).unique();for(const grant of await ctx.db.query('pilotEntitlements').withIndex('by_user',q=>q.eq('userId',u!._id)).take(10))await ctx.db.patch(grant._id,{endsAt:now+4.5*86400000});});generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);return {text:JSON.stringify(p.task?.startsWith('Check independent')?{complete:true,missing:[]}:{reply:'Your Pilates reminders are now 9:30 am on Tuesday, Thursday and Saturday.'})};});const text='Change my Pilates reminder to 9:30 am every Tuesday Thursday and Saturday. My Pilates sessions are 10 am.';const result=await send(text,{introduced:true,reply:'Updated Pilates reminders.',actions:shape==='group'?[{type:'correct',targetId:old._id,evidence:'9:30 am every Tuesday Thursday and Saturday',datePhrase:'every Tuesday Thursday and Saturday',timePhrase:'9:30 am',repeat:'weekly'}]:[...(shape==='remove'?[{type:'remove',targetId:old._id,state:'cancelled',evidence:text}]:[]),...['Tuesday','Thursday','Saturday'].map(day=>({type:'reminder',targetId:id,evidence:text,permissionEvidence:text,datePhrase:day,timePhrase:'9:30 am',repeat:'weekly'}))],tasks:[]},'replace-weekly');const jobs=await t.query(q('pilotReminders:view'),{token});if(failThird){expect(result.outcome).toBe('error');expect(jobs).toHaveLength(1);expect(jobs[0]).toMatchObject({_id:old._id,state:'active',repeat:'once'});return;}expect(result.outcome).toBe('conversation');expect(jobs.find((r:any)=>r._id===old._id).state).toBe('stopped');const active=jobs.filter((r:any)=>r.state==='active');expect(active).toHaveLength(3);expect(active.every((r:any)=>r.repeat==='weekly'&&r.localTime==='09:30')).toBe(true);const after=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''});expect(after.state.records[0]).toMatchObject({time:'10 am',targetNumber:3});});

