test('answering an old task does not retire a new question that reused its id (simulated AI)',async()=>{
 const {t,token,send}=await setup();await send('I do Pilates four times weekly',{introduced:true,reply:'Kept your target. Which days do you go?',clarification:'Which days do you go?',actions:[{type:'save',kind:'plan',label:'Pilates',evidence:'Pilates four times weekly',targetNumber:4}],tasks:[{id:'days',topic:'Pilates days',question:'Which days do you go?'}]},'initial-days');
 const before=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''}),id=before.state.records[0].id,oldTask=before.state.tasks.find((x:any)=>x.topic==='Pilates days');
 generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent')){const aliases=p.unfinishedQuestions.map((x:any)=>x.id);return {text:JSON.stringify({complete:true,missing:[],answeredTaskIds:aliases})};}if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:'Kept Monday through Thursday. '+(p.question??'')})};return {text:JSON.stringify({introduced:true,reply:'Kept Monday through Thursday. What time do you go?',clarification:'What time do you go?',actions:[{type:'correct',targetId:id,evidence:'Monday to Thursday',text:'Monday to Thursday'}],tasks:[{id:oldTask.id,topic:'Pilates time',sourceMessageId:'new-days',targetId:id,question:'What time do you go?'}]})};});
 const result=await t.action(api.messages.send,{token,messageId:'new-days',text:'Monday to Thursday'});expect(result.message).toContain('What time do you go?');const after=(await t.query(q('v4Store:context'),{token,messageId:'peek',text:''})).state;expect(after.tasks.some((x:any)=>x.topic==='Pilates time'&&x.question==='What time do you go?')).toBe(true);expect(after.records[0].text).toBe('Monday to Thursday');expect(after.records[0].targetNumber).toBe(4);
});

test('owned retrieval answers without reviving independently irrelevant workout setup (simulated AI)',async()=>{
 const {t,token,send}=await setup();await send('My protein target is 55 to 65 grams daily',{introduced:true,reply:'Kept the target.',actions:[{type:'save',kind:'food',label:'protein target',evidence:'My protein target is 55 to 65 grams daily',useSourceText:true}],tasks:[]},'protein');
 const before=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''});const foodId=before.state.records[0].id;
 await send('I do Pilates twice weekly',{introduced:true,reply:'Kept Pilates. Which days do you go?',clarification:'Which days do you go?',actions:[{type:'save',kind:'plan',label:'Pilates',evidence:'Pilates twice weekly',targetNumber:2}],tasks:[{id:'pilates-days',topic:'Pilates days',question:'Which days do you go?'}]},'pilates');
 generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:true,missing:[],irrelevantConversationQuestion:'Which days do you go?',conversationEvidence:'What protein target did I tell you?',firstTaskQuestion:null})};if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:'Your protein target is 55 to 65 grams daily.'+(p.question?' '+p.question:'')})};return {text:JSON.stringify({introduced:true,reply:'Your protein target is 55 to 65 grams daily. Which days do you go?',clarification:'Which days do you go?',actions:[{type:'retrieve',targetId:foodId,evidence:'protein target'}],tasks:before.state.tasks})};});
 const result=await t.action(api.messages.send,{token,messageId:'protein-retrieval',text:'What protein target did I tell you?'});expect(result.message).not.toContain('?');const after=(await t.query(q('v4Store:context'),{token,messageId:'peek',text:''})).state;expect(after.records).toHaveLength(2);expect(after.tasks.some((x:any)=>x.topic==='Pilates days'&&x.question===null)).toBe(true);
});


