for(const answer of ['The same one.','A new one.'])test('a same-day repeat report asks same or new, then '+answer+' is honoured (simulated AI, phone test 22 Oct)',async()=>{
 const {t,token}=await setup();const night='I woke up twice last night',ask='Is that the same as what you told me earlier, or a new one? I haven’t added it again yet.';
 const save=(id:string)=>({introduced:true,reply:'Noted that you woke up twice last night.',actions:[{type:'save',kind:'event',label:night,sourceMessageId:id,evidence:night,text:night,datePhrase:'last night',state:'completed'}],tasks:[]});
 generate.mockImplementation(async(_c:any,_u:any,o:any)=>{const p=JSON.parse(o.prompt);if(p.task?.startsWith('Check independent'))return {text:JSON.stringify({complete:true,missing:[]})};if(p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:p.question??(p.proposal?.actions?.length?'Noted, a new one.':'Okay, I’ll leave it as one.')})};if(p.task)return {text:JSON.stringify({reply:'x'})};const cur=p.input.currentMessage;
  if(cur.text===night)return {text:JSON.stringify(save(cur.messageId))};
  return {text:JSON.stringify(answer==='A new one.'?{...save('again'),reply:'Noted, a new one.'}:{introduced:true,reply:'Okay, I’ll leave it as one.',actions:[],tasks:[]})};});
 await t.action(api.messages.send,{token,messageId:'first',text:night});
 const r=await t.action(api.messages.send,{token,messageId:'again',text:night});expect(r.outcome).toBe('conversation');expect(r.message).toBe(ask);
 let c=await t.query(q('v4Store:context'),{token,messageId:'peek',text:''});expect(c.state.records.filter((x:any)=>x.kind==='event')).toHaveLength(1);expect(c.state.tasks.filter((x:any)=>x.question===ask)).toHaveLength(1);
 const done=await t.action(api.messages.send,{token,messageId:'answer',text:answer});expect(done.outcome).toBe('conversation');
 c=await t.query(q('v4Store:context'),{token,messageId:'peek2',text:''});expect(c.state.records.filter((x:any)=>x.kind==='event')).toHaveLength(answer==='A new one.'?2:1);
});
