test('a missing lookup action can be repaired without saving the question or changing existing records (simulated AI)',async()=>{
 const {t,token,send}=await setup();
 await send('I do swimming twice a week',{introduced:true,reply:'Saved swimming twice a week.',actions:[{type:'save',kind:'plan',label:'swimming',targetNumber:2,evidence:'swimming twice a week'}],tasks:[]},'lookup-plan');
 const before=await t.query(q('v4Store:context'),{token,messageId:'peek-before',text:''});
 const text='Show my saved workout plan.';
 generate.mockImplementation(async(_ctx:any,_user:any,o:any)=>{
  const p=JSON.parse(o.prompt);
  if(p.task?.startsWith('Check independent')){const hasLookup=p.proposal.actions.some((a:any)=>a.type==='retrieve');return {text:JSON.stringify({complete:hasLookup,missing:hasLookup?[]:[text]})};}
  if(p.task?.startsWith('Return JSON ONLY {actions:[],more:boolean,tasks?:[]}'))return {text:JSON.stringify({actions:[{type:'retrieve',sourceMessageId:p.currentSource.messageId,evidence:text}],more:false,tasks:[]})};
  if(p.task?.startsWith('Return JSON only {reply:string}')||p.task?.startsWith('Respond with'))return {text:JSON.stringify({reply:'Your saved plan is swimming twice a week.'})};
  return {text:JSON.stringify({introduced:true,reply:'Your saved plan is swimming twice a week.',actions:[],tasks:[],more:false})};
 });
 const result=await t.action(api.messages.send,{token,messageId:'lookup-repair',text});
 expect(result.outcome).toBe('conversation');expect(result.message).toContain('swimming twice a week');
 const after=await t.query(q('v4Store:context'),{token,messageId:'peek-after',text:''});
 expect(after.state.records).toEqual(before.state.records);expect(after.state.reminders).toEqual(before.state.reminders);
});
